// The copy of the @pegasys/v3-core/contracts/PegasysV3Factory.sol
// TODO: should always be up to date with the original contract
// Only differences:
// - Relative imports(path was changed)
// - Updated PegasysV3PoolDeployer implementation, and initialization.

// SPDX-License-Identifier: BUSL-1.1
pragma solidity =0.7.6;

import '@pegasys/v3-core/contracts/interfaces/IPegasysV3Factory.sol';

import './MockTimePegasysV3PoolDeployer.sol';
import '@pegasys/v3-core/contracts/NoDelegateCall.sol';

import '@pegasys/v3-core/contracts/PegasysV3Pool.sol';

/// @title Canonical Pegasys V3 factory
/// @notice Deploys Pegasys V3 pools and manages ownership and control over pool protocol fees
contract MockTimePegasysV3Factory is IPegasysV3Factory, MockTimePegasysV3PoolDeployer, NoDelegateCall {
    /// @inheritdoc IPegasysV3Factory
    address public override owner;

    /// @inheritdoc IPegasysV3Factory
    mapping(uint24 => int24) public override feeAmountTickSpacing;
    /// @inheritdoc IPegasysV3Factory
    mapping(address => mapping(address => mapping(uint24 => address))) public override getPool;

    constructor(TimeSimulator _timeSimulator) MockTimePegasysV3PoolDeployer(_timeSimulator) {
        owner = msg.sender;
        emit OwnerChanged(address(0), msg.sender);

        feeAmountTickSpacing[500] = 10;
        emit FeeAmountEnabled(500, 10);
        feeAmountTickSpacing[3000] = 60;
        emit FeeAmountEnabled(3000, 60);
        feeAmountTickSpacing[10000] = 200;
        emit FeeAmountEnabled(10000, 200);
    }

    /// @inheritdoc IPegasysV3Factory
    function createPool(
        address tokenA,
        address tokenB,
        uint24 fee
    ) external override noDelegateCall returns (address pool) {
        require(tokenA != tokenB);
        (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        require(token0 != address(0));
        int24 tickSpacing = feeAmountTickSpacing[fee];
        require(tickSpacing != 0);
        require(getPool[token0][token1][fee] == address(0));
        pool = deploy(address(this), token0, token1, fee, tickSpacing);
        getPool[token0][token1][fee] = pool;
        // populate mapping in the reverse direction, deliberate choice to avoid the cost of comparing addresses
        getPool[token1][token0][fee] = pool;
        emit PoolCreated(token0, token1, fee, tickSpacing, pool);
    }

    /// @inheritdoc IPegasysV3Factory
    function setOwner(address _owner) external override {
        require(msg.sender == owner);
        emit OwnerChanged(owner, _owner);
        owner = _owner;
    }

    /// @inheritdoc IPegasysV3Factory
    function enableFeeAmount(uint24 fee, int24 tickSpacing) public override {
        require(msg.sender == owner);
        require(fee < 1000000);
        // tick spacing is capped at 16384 to prevent the situation where tickSpacing is so large that
        // TickBitmap#nextInitializedTickWithinOneWord overflows int24 container from a valid tick
        // 16384 ticks represents a >5x price change with ticks of 1 bips
        require(tickSpacing > 0 && tickSpacing < 16384);
        require(feeAmountTickSpacing[fee] == 0);

        feeAmountTickSpacing[fee] = tickSpacing;
        emit FeeAmountEnabled(fee, tickSpacing);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity =0.7.6;

import '@pegasys/v3-core/contracts/PegasysV3Pool.sol';
import '../TimeSimulator.sol';

// used for testing time dependent behavior
contract MockTimePegasysV3Pool is PegasysV3Pool {
    TimeSimulator timeSimulator;

    function setTimeSimulator(TimeSimulator _timeSimulator) external {
        timeSimulator = _timeSimulator;
    }

    function _blockTimestamp() internal view override returns (uint32) {
        return uint32(timeSimulator.blockTimestamp());
    }
}

// The copy of the @pegasys/v3-core/contracts/PegasysV3PoolDeployer.sol
// TODO: should always be up to date with the original contract
// Only differences:
// - Relative imports(path was changed)
// - Added TimeSimulator import
// - Added time simulator immutable and initialization in the constructor.
// - Updated pool implementation, added time simulator initialization.

// SPDX-License-Identifier: BUSL-1.1
pragma solidity =0.7.6;

import '@pegasys/v3-core/contracts/interfaces/IPegasysV3PoolDeployer.sol';

import './MockTimePegasysV3Pool.sol';

import '../TimeSimulator.sol';

contract MockTimePegasysV3PoolDeployer is IPegasysV3PoolDeployer {
    TimeSimulator immutable timeSimulator;

    constructor(TimeSimulator _timeSimulator) {
        timeSimulator = _timeSimulator;
    }

    struct Parameters {
        address factory;
        address token0;
        address token1;
        uint24 fee;
        int24 tickSpacing;
    }

    /// @inheritdoc IPegasysV3PoolDeployer
    Parameters public override parameters;

    /// @dev Deploys a pool with the given parameters by transiently setting the parameters storage slot and then
    /// clearing it after deploying the pool.
    /// @param factory The contract address of the Pegasys V3 factory
    /// @param token0 The first token of the pool by address sort order
    /// @param token1 The second token of the pool by address sort order
    /// @param fee The fee collected upon every swap in the pool, denominated in hundredths of a bip
    /// @param tickSpacing The spacing between usable ticks
    function deploy(
        address factory,
        address token0,
        address token1,
        uint24 fee,
        int24 tickSpacing
    ) internal returns (address pool) {
        parameters = Parameters({factory: factory, token0: token0, token1: token1, fee: fee, tickSpacing: tickSpacing});
        pool = address(new MockTimePegasysV3Pool{salt: keccak256(abi.encode(token0, token1, fee))}());
        MockTimePegasysV3Pool(pool).setTimeSimulator(timeSimulator);
        delete parameters;
    }
}

